UPDATE device_tokens
SET is_active = 0, updated_at = UTC_TIMESTAMP()
WHERE token = #{token}

UPDATE device_tokens
SET is_active = 0, updated_at = UTC_TIMESTAMP()
WHERE user_id = #{userId}

UPDATE device_tokens
SET last_used_at = UTC_TIMESTAMP(), updated_at = UTC_TIMESTAMP()
WHERE id = #{id}
